def transform(grid):
    g = np.array(grid)
    H, W = g.shape
    bg = 7
    # find wall: a full border line not of bg
    d = None
    for (y, c) in dividers(g)["rows"]:
        if c != bg and c != 8 and c != 2:
            if y == 0: d = (-1, 0)
            elif y == H - 1: d = (1, 0)
    for (x, c) in dividers(g)["cols"]:
        if c != bg and c != 8 and c != 2:
            if x == 0: d = (0, -1)
            elif x == W - 1: d = (0, 1)
    out = g.copy()
    eights = [(y, x) for y in range(H) for x in range(W) if g[y, x] == 8]
    outside = []
    for (y, x) in eights:
        n2 = n7 = 0
        for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            yy, xx = y + dy, x + dx
            if 0 <= yy < H and 0 <= xx < W:
                if g[yy, xx] == 2: n2 += 1
                elif g[yy, xx] == bg: n7 += 1
        if n2 > n7:
            out[y, x] = 2
        else:
            outside.append((y, x))
    emit(out, "Erase 8s lying inside the 2 region (turn them into 2).")
    if d is not None:
        for (y, x) in outside:
            yy, xx = y + d[0], x + d[1]
            if 0 <= yy < H and 0 <= xx < W and g[yy, xx] == bg:
                out[yy, xx] = 8
    emit(out, "Extend each background 8 by one cell toward the 9 wall.")
    return out
